# Multiple versions and multiple editions might be installed, so we iterate over versions installed.
# If version preference is given, we filter only matching versions, othervise the highest version is picked.
def has_editions(version: Path) -> bool:
    # The version should have at least one known edition installed inside it.
    return any(e.name in edition_preferences for e in version.iterdir())

def matches_version_preference(version: Path) -> bool:
    return version_preference is None or version.name == version_preference

installed_versions = []
for mvs_path in mvs_paths:
    for version in mvs_path.iterdir():
        if (
            version.is_dir()
            and has_editions(version)
            and matches_version_preference(version)
        ):
            installed_versions.append(version)

mvs_versions = sorted(
    installed_versions,
    key=lambda p: p.name,
    reverse=True,
)
